const s="lc_ebbinghaus_problems";function c(e=new Date){const o=e.getFullYear(),t=String(e.getMonth()+1).padStart(2,"0"),a=String(e.getDate()).padStart(2,"0");return`${o}-${t}-${a}`}async function r(){try{const o=(await chrome.storage.local.get([s]))[s]||[],t=c();let a=0;for(const n of o)n.nextReviewDate<=t&&n.lastReviewedDate!==t&&(a+=1);a>0?(await chrome.action.setBadgeText({text:String(a)}),await chrome.action.setBadgeBackgroundColor({color:"#ef4444"})):(await chrome.action.setBadgeText({text:""}),await chrome.action.setBadgeBackgroundColor({color:"#10b981"}))}catch(e){console.error("Failed to update badge:",e)}}chrome.runtime.onInstalled.addListener(()=>{chrome.alarms.create("ebbinghaus-badge-refresh",{periodInMinutes:30}),r()});chrome.alarms.onAlarm.addListener(e=>{e.name==="ebbinghaus-badge-refresh"&&r()});chrome.runtime.onMessage.addListener((e,o,t)=>{e.type==="UPDATE_BADGE"&&(r(),t({success:!0}))});
